package ru.murad.yourmarket.service;import org.junit.jupiter.api.Test;import ru.murad.yourmarket.mapper.AdvertisementMapper;import ru.murad.yourmarket.model.Advertisement;import ru.murad.yourmarket.model.enums.AdvertisementStatus;import ru.murad.yourmarket.repository.AdvertisementRepository;import ru.murad.yourmarket.service.impl.AdvertisementServiceImpl;import java.util.UUID;import static org.mockito.Mockito.*;
class AdvertisementServiceTest {AdvertisementRepository repo=mock(AdvertisementRepository.class);AdvertisementMapper mapper=mock(AdvertisementMapper.class);ChannelMessageDeletionService deletion=mock(ChannelMessageDeletionService.class);AdvertisementLifecycleTransactionService lifecycle=mock(AdvertisementLifecycleTransactionService.class);AdvertisementServiceImpl service=new AdvertisementServiceImpl(repo,mapper,deletion,lifecycle);
@Test void completedDeleteIsIdempotent(){UUID id=UUID.randomUUID();when(lifecycle.authorizeDeletion(id,1L)).thenReturn(Advertisement.builder().id(id).status(AdvertisementStatus.DELETED).build());service.deletePublished(id,1L);verifyNoInteractions(deletion);}}
